        "passage": "わたしは 今年の 春から、駅の 近くの 居酒屋で アルバイトを しています。最初は 注文を 聞いたり、料理を 運んだり する だけでも 精一杯（せいいっぱい）で、毎日 失敗ばかり して いました。\nいちばん つらかったのは、働き始めて 2週間目の 金曜日の 夜です。店が とても 混んで いて、わたしは 焦って いました。お客さんから 頼まれた ビールを テーブルへ 運ぶ とき、足が 滑って ビールを お客さんの スーツに こぼして しまったのです。わたしは 頭が 真っ白に なって、「すみません！」と 言う だけで 何も できませんでした。すると、すぐに 店長が 飛んで 来て、おしぼり（タオル）で スーツを ふきながら、お客さんに 深く 頭を 下げて 謝って くれました。\nその 夜、店が 閉まった あと、わたしは 「もう アルバイトを 辞めよう」と 思って 店長に 相談しました。しかし、店長は 怒る どころか、優しく こう 言って くれました。「最初は だれでも 失敗するよ。大切なのは、同じ 失敗を 繰り返さない ように 工夫する ことだ。混んで いる ときほど、ゆっくり 歩いて 周りを よく 見るんだよ」。\nその 言葉に 励まされて、わたしは もう一度 がんばる ことに しました。それからは、混んで いる ときでも 深呼吸をして 落ち着いて 行動する ように 心がけて います。今では 先輩から 「最近、動きが すごく よくなったね」と ほめられる ように なりました。あの とき 諦めないで 本当に よかったです。",
